import numpy as np; W=dict(np.load('weights.npz'))
U=[];V=[]
for l in range(4):
  for h in range(6):
    s=slice(64*h,64*h+64)
    M=(W[f'W_q.{l}'][s]*W[f'ln1_w.{l}']).T@(W[f'W_k.{l}'][s]*W[f'ln1_w.{l}'])
    u,sv,vt=np.linalg.svd(M); U.append(u[:,0]);V.append(vt[0])
U=np.array(U);V=np.array(V)
np.set_printoptions(linewidth=250)
