print(np.round(np.abs(U@V.T).diagonal(),2))
for n in ['W_fc.0','W_fc.1','W_fc.2','W_fc.3','W_k.1']:
  v=np.linalg.svd(W[n])[2][0]; print(n,np.round(np.abs(V@v),2))

