import numpy as np; W=dict(np.load('weights.npz'))
def mats(l,h):
    s=slice(64*h,64*h+64); g=W[f'ln1_w.{l}']
    QK=(W[f'W_q.{l}'][s]*g).T@(W[f'W_k.{l}'][s]*g)
    OV=W[f'W_o.{l}'][:,s]@(W[f'W_v.{l}'][s]*g)
    return QK,OV
for l in range(4):
  for h in range(6):
    QK,OV=mats(l,h)
    ev=np.linalg.eigvals(OV).real
    print(l,h,'QKsym %.2f'%(np.trace(QK)/np.linalg.norm(QK)), 'OVcopy %.2f'%(np.trace(OV)/np.linalg.norm(OV)), 'OVfro %.2f'%np.linalg.norm(OV),
          'Kcomp', ' '.join('%.2f'%(np.linalg.norm(QK@mats(0,j)[1])/np.linalg.norm(QK)/np.linalg.norm(mats(0,j)[1])) for j in range(6)) if l>0 else '')

